import{_ as a,o,c as t,ae as d}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"Pila tecnológica","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/03-pila-tecnologica.md","filePath":"es/reference/03-pila-tecnologica.md"}'),r={name:"es/reference/03-pila-tecnologica.md"};function n(i,e,s,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="pila-tecnologica" tabindex="-1">Pila tecnológica <a class="header-anchor" href="#pila-tecnologica" aria-label="Permalink to &quot;Pila tecnológica&quot;">​</a></h1><p>Todas las tecnologías y frameworks del proyecto y su rol — la UI, el renderizado del mapa, los generadores de malla, el motor, el servidor y el tooling.</p><h2 id="propiedades-clave" tabindex="-1">Propiedades clave <a class="header-anchor" href="#propiedades-clave" aria-label="Permalink to &quot;Propiedades clave&quot;">​</a></h2><p>Del resumen del proyecto:</p><ul><li><strong>Sin backend.</strong> El único servidor es un servidor trivial de archivos estáticos + endpoint de salud (<code>server.py</code>). Sin base de datos, sin paso de build para la UI, sin bundler.</li><li><strong>Sin framework de UI.</strong> El frontend son ~15.000 líneas de JavaScript sin dependencias (scripts clásicos + IIFEs) que usa Mapbox GL JS como única librería de runtime pesada.</li><li><strong>Hidráulica embebida en WASM.</strong> El motor OpenSWMM 6.0.0 se cross-compila para <code>wasm32-emscripten</code> con dependencias C++ gestionadas por vcpkg (Eigen, HDF5, nlohmann-json, SUNDIALS).</li><li><strong>Dos backends de simulación.</strong> Una vía de motor WASM (1D + 1D/2D acoplado) y un backend <strong>WebGPU experimental</strong> que reimplementa el solver 2D explícito local-inercial como kernels de cómputo WGSL y lo ejecuta en paralelo al motor WASM.</li><li><strong>Dos generadores de malla.</strong> Un generador legado basado en <code>poly2tri</code> y el pipeline de producción <strong>Shewchuk Triangle WASM</strong> (npm <code>triangle-wasm</code>).</li></ul><h2 id="pila-por-capa" tabindex="-1">Pila por capa <a class="header-anchor" href="#pila-por-capa" aria-label="Permalink to &quot;Pila por capa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capa</th><th>Tecnología</th><th>Notas</th></tr></thead><tbody><tr><td>Lenguaje (UI)</td><td>JavaScript plano (ES2020+, IIFEs)</td><td>Sin TypeScript, sin módulos, sin bundler</td></tr><tr><td>Renderizado del mapa</td><td>Mapbox GL JS v3.1.2 (CDN)</td><td>Terreno 3D, edificios, fuentes GeoJSON, capas WebGL2 personalizadas</td></tr><tr><td>Matemática de coordenadas</td><td>proj4js 2.9.0 (CDN)</td><td>UTM/proyectado → WGS84 al importar</td></tr><tr><td>Parsers GIS</td><td>shpjs 4.0.4, dxf-parser 1.1.2 (CDN)</td><td>Importación de Shapefile + DXF</td></tr><tr><td>Triangulación 2D</td><td>poly2tri 1.5.0 (legado) <strong>y</strong> triangle-wasm 1.0.0 (producción, vendorizado)</td><td>Port de Shewchuk Triangle</td></tr><tr><td>Rasters</td><td>geotiff 2.1.3 (CDN)</td><td>Muestreo de DEM local (GeoTIFF)</td></tr><tr><td>Motor</td><td>OpenSWMM 6.0.0-alpha (C++20)</td><td>Compilado con Emscripten 6.x a WASM</td></tr><tr><td>Deps C++</td><td>eigen3, hdf5, nlohmann-json, sundials</td><td>vía vcpkg, triplet wasm32-emscripten</td></tr><tr><td>Lenguaje (servidor)</td><td>Python 3 stdlib (<code>http.server</code>)</td><td>Cero dependencias</td></tr><tr><td>Lenguaje (tooling)</td><td>Node.js (≥20)</td><td>Scripts de bench/verify/harness, <code>npm</code></td></tr><tr><td>CI / hosting</td><td>GitHub Actions → GitHub Pages</td><td>Solo deploy estático</td></tr></tbody></table><h2 id="dependencias-cdn" tabindex="-1">Dependencias CDN <a class="header-anchor" href="#dependencias-cdn" aria-label="Permalink to &quot;Dependencias CDN&quot;">​</a></h2><p><strong>Dependencias CDN cargadas por <code>index.html</code></strong> (todas fijadas por versión, restringidas por CSP a <code>api.mapbox.com</code>, <code>cdn.jsdelivr.net</code>, <code>cdnjs.cloudflare.com</code>, <code>unpkg.com</code>, <code>maps.googleapis.com</code>): <code>mapbox-gl-js@3.1.2</code>, <code>proj4js@2.9.0</code>, <code>shpjs@4.0.4</code>, <code>dxf-parser@1.1.2</code>, <code>poly2tri@1.5.0</code>, <code>geotiff@2.1.3</code> y (opcionalmente) la Google Maps JS API.</p>',9)])])}const h=a(r,[["render",n]]);export{m as __pageData,h as default};
